<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxConfirmDialog from'../../components/ui/NxConfirmDialog.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{createOltDevice,createOltProfile,deleteOltDevice,deleteOltProfile,getOltDevice,getOltProfile,listOltDevices,listOltPorts,listOltProfiles,previewOltProfile,updateOltDevice,updateOltProfile}from'./api';import type{OltDevice,OltDevicePayload,OltMode,OltPort,OltProfile,ProfileType}from'./contracts';
const props=withDefaults(defineProps<{mode?:OltMode;initialOltId?:number;initialProfileTab?:ProfileType}>(),{mode:'devices',initialOltId:0,initialProfileTab:'dba'});const devices=ref<OltDevice[]>([]),ports=ref<OltPort[]>([]),profiles=ref<OltProfile[]>([]),selectedOltId=ref(props.initialOltId),profileTab=ref<ProfileType>(props.initialProfileTab),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),modalError=ref('');const deviceModal=ref(false),detailModal=ref(false),portModal=ref(false),profileModal=ref(false),configurationModal=ref(false),cliModal=ref(false),editingDevice=ref<OltDevice|null>(null),viewDevice=ref<OltDevice|null>(null),viewPort=ref<OltPort|null>(null),viewConfiguration=ref<OltProfile|null>(null),editingProfile=ref<OltProfile|null>(null),pendingDelete=ref<{kind:'device'|'profile';row:OltDevice|OltProfile}|null>(null),cli=ref('');const deviceForm=reactive<OltDevicePayload>({name:'',ip_address:'',vendor:'Huawei',username:'',password:'',enable_home_gateway_omci:0,auto_detect_omci_support:1});const profileForm=reactive<Record<string,unknown>>({});
const selectedDevice=computed(()=>devices.value.find(d=>Number(d.id)===Number(selectedOltId.value)));const q=computed(()=>search.value.trim().toLowerCase());const deviceRows=computed(()=>devices.value.filter(r=>!q.value||JSON.stringify(r).toLowerCase().includes(q.value)));const portRows=computed(()=>ports.value.filter(r=>!q.value||JSON.stringify(r).toLowerCase().includes(q.value)));const profileRows=computed(()=>profiles.value.filter(r=>!q.value||JSON.stringify(r).toLowerCase().includes(q.value)));const profileFields:Record<ProfileType,[string,string,string][]>={dba:[['profile_id','Profile ID','number'],['profile_name','Profile Name','text'],['max_bandwidth','Max Bandwidth','number'],['description','Description','text']],line:[['profile_id','Profile ID','number'],['profile_name','Profile Name','text'],['customer_cvlan','Customer C-VLAN','number'],['management_vlan','Management VLAN','number'],['dba_profile_id','DBA Profile ID','number'],['description','Description','text']],wan:[['profile_id','Profile ID','number'],['profile_name','Profile Name','text'],['wan_mode','WAN Mode (pppoe/dhcp)','text'],['description','Description','text']],tr069:[['profile_id','Profile ID','number'],['profile_name','Profile Name','text'],['acs_url','ACS URL','text'],['acs_username','ACS Username','text'],['acs_password','ACS Password','password'],['description','Description','text']],srv:[['profile_id','Profile ID','number'],['profile_name','Profile Name','text'],['eth_ports','ETH Ports','number'],['description','Description','text']]};
function clear(){error.value='';notice.value='';modalError.value='';}function tone(v?:string):'success'|'danger'|'warning'|'neutral'{const s=String(v||'').toLowerCase();return['online','active','up','normal'].includes(s)?'success':['offline','down','failed','fault'].includes(s)?'danger':'neutral';}function portPath(p:OltPort){return p.port_path||`${p.frame??0}/${p.slot??0}/${p.port??0}`;}async function load(showNotice=false){loading.value=true;clear();try{devices.value=await listOltDevices();if(!selectedOltId.value&&devices.value.length)selectedOltId.value=Number(devices.value[0].id);if(props.mode==='ports'&&selectedOltId.value)ports.value=await listOltPorts(selectedOltId.value);if(props.mode==='profiles'&&selectedOltId.value)profiles.value=await listOltProfiles(profileTab.value,selectedOltId.value);if(showNotice)notice.value='OLT workspace refreshed.';}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to load OLT workspace.';}finally{loading.value=false;}}
function configurationEntries(p:OltProfile|null){return Object.entries(p||{}).filter(([k])=>!['id','olt_id','profile_id','profile_name','description','created_at','updated_at','acs_password'].includes(k));}function showConfiguration(p:OltProfile){viewConfiguration.value=p;configurationModal.value=true;}
async function loadScoped(){clear();if(!selectedOltId.value){ports.value=[];profiles.value=[];return;}loading.value=true;try{if(props.mode==='ports')ports.value=await listOltPorts(selectedOltId.value);if(props.mode==='profiles')profiles.value=await listOltProfiles(profileTab.value,selectedOltId.value);}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to load selected OLT.';}finally{loading.value=false;}}
function openNewDevice(){editingDevice.value=null;Object.assign(deviceForm,{name:'',ip_address:'',vendor:'Huawei',username:'',password:'',enable_home_gateway_omci:0,auto_detect_omci_support:1});deviceModal.value=true;}async function openEditDevice(row:OltDevice){const fresh=await getOltDevice(row.id);editingDevice.value=fresh;Object.assign(deviceForm,{name:fresh.name,ip_address:fresh.ip_address,vendor:fresh.vendor||'Huawei',username:fresh.username,password:fresh.password||'',enable_home_gateway_omci:Number(fresh.enable_home_gateway_omci||0),auto_detect_omci_support:Number(fresh.auto_detect_omci_support||0)});deviceModal.value=true;}async function submitDevice(){modalError.value='';if(!deviceForm.name||!deviceForm.ip_address||!deviceForm.username||!deviceForm.password){modalError.value='Name, IP address, username, and password are required.';return;}saving.value=true;try{const result=editingDevice.value?await updateOltDevice(editingDevice.value.id,{...deviceForm}):await createOltDevice({...deviceForm});deviceModal.value=false;await load();notice.value=result.message||'OLT device saved.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Unable to save OLT device.';}finally{saving.value=false;}}
function openNewProfile(){editingProfile.value=null;Object.keys(profileForm).forEach(k=>delete profileForm[k]);profileForm.olt_id=selectedOltId.value;profileFields[profileTab.value].forEach(f=>profileForm[f[0]]='');profileModal.value=true;}async function openEditProfile(row:OltProfile){const fresh=await getOltProfile(profileTab.value,row.id);editingProfile.value=fresh;Object.keys(profileForm).forEach(k=>delete profileForm[k]);Object.assign(profileForm,fresh,{olt_id:selectedOltId.value});if(profileTab.value==='tr069')profileForm.acs_password='';profileModal.value=true;}async function submitProfile(){saving.value=true;modalError.value='';try{const result=editingProfile.value?await updateOltProfile(profileTab.value,editingProfile.value.id,{...profileForm}):await createOltProfile(profileTab.value,{...profileForm});profileModal.value=false;await loadScoped();notice.value=result.message||'OLT profile saved.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Unable to save OLT profile.';}finally{saving.value=false;}}async function showCli(row:OltProfile){try{const result=await previewOltProfile(profileTab.value,row.id);cli.value=String(result.cli||result.config||result.output||JSON.stringify(result,null,2));cliModal.value=true;}catch(reason){error.value=reason instanceof Error?reason.message:'Unable to generate CLI preview.';}}async function executeDelete(){if(!pendingDelete.value)return;saving.value=true;modalError.value='';try{const result=pendingDelete.value.kind==='device'?await deleteOltDevice((pendingDelete.value.row as OltDevice).id):await deleteOltProfile(profileTab.value,(pendingDelete.value.row as OltProfile).id);pendingDelete.value=null;await load();notice.value=result.message||'OLT record deleted.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Delete failed.';}finally{saving.value=false;}}
watch([selectedOltId,profileTab],()=>void loadScoped());onMounted(()=>void load());
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Access and uplink infrastructure" :title="mode==='devices'?'OLT Management':mode==='ports'?'OLT Ports Console':'OLT Profiles'" :description="mode==='devices'?'Device registry and connection profiles':mode==='ports'?'Imported physical and logical port state':'DBA, Line, WAN, TR069, and Service profiles scoped to an OLT'"><template #actions><a v-if="mode!=='devices'" href="/olt-management" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-4 text-sm font-semibold no-underline">Back to Devices</a><a v-if="mode==='ports'" :href="`/olt-management/ports?olt_id=${selectedOltId}&legacy_ui=1`" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-4 text-sm font-semibold text-[var(--nx-text)] no-underline">Discovery & VLAN Assignment</a><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton v-if="mode==='devices'" @click="openNewDevice">Add Device</NxButton><NxButton v-if="mode==='profiles'&&selectedOltId" @click="openNewProfile">Add {{profileTab.toUpperCase()}} Profile</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert>
<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="item in mode==='devices'?[['Devices',devices.length,'Registered OLTs'],['Vendors',new Set(devices.map(d=>d.vendor)).size,'Distinct vendors'],['Addressed',devices.filter(d=>d.ip_address).length,'With management IP'],['Credential Ready',devices.filter(d=>d.username&&d.password).length,'Stored access profiles']]:mode==='ports'?[['Selected OLT',selectedDevice?.name||'None',selectedDevice?.ip_address||'Choose an OLT'],['Ports',ports.length,'Imported records'],['Link Online',ports.filter(p=>String(p.link_status).toLowerCase()==='online').length,'Operational links'],['ONT Online',ports.reduce((n,p)=>n+Number(p.ont_online||0),0),'Across GPON ports']]:[['Selected OLT',selectedDevice?.name||'None',selectedDevice?.ip_address||'Choose an OLT'],['Profile Type',profileTab.toUpperCase(),'Active workspace'],['Profiles',profiles.length,'Loaded for this OLT'],['Vendor',selectedDevice?.vendor||'—','OLT platform']]" :key="String(item[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0]}}</p><p class="mt-2 text-xl font-bold">{{item[1]}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{item[2]}}</p></NxCard></section>
<NxToolbar><div class="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between"><label v-if="mode!=='devices'" class="grid gap-1 text-sm font-semibold">OLT Device<select v-model.number="selectedOltId" class="min-h-11 rounded-md bg-[var(--nx-surface-muted)] px-3"><option :value="0">Select OLT</option><option v-for="d in devices" :key="d.id" :value="d.id">{{d.name}} · {{d.ip_address}}</option></select></label><div v-if="mode==='profiles'" role="tablist" class="flex flex-wrap gap-2"><button v-for="t in ['dba','line','wan','tr069','srv']" :key="t" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="profileTab===t?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="profileTab=t as ProfileType">{{t.toUpperCase()}}</button></div><input v-model="search" type="search" :placeholder="`Search ${mode}…`" class="min-h-11 w-full rounded-md bg-[var(--nx-surface-muted)] px-4 lg:max-w-sm"></div></NxToolbar>
<NxTableShell v-if="mode==='devices'" min-width="980px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Device</th><th class="px-4 py-3">Management</th><th class="px-4 py-3">Vendor</th><th class="px-4 py-3">OMCI</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!deviceRows.length"><td colspan="5" class="px-4 py-12 text-center">No OLT devices found.</td></tr><tr v-for="d in deviceRows" :key="d.id"><td class="px-4 py-3"><p class="font-semibold">{{d.name}}</p><p class="text-xs text-[var(--nx-text-muted)]">OLT ID {{d.id}}</p></td><td class="px-4 py-3"><p class="font-mono">{{d.ip_address}}</p><p class="text-xs text-[var(--nx-text-muted)]">{{d.username}}</p></td><td class="px-4 py-3">{{d.vendor||'—'}}</td><td class="px-4 py-3"><NxBadge :tone="Number(d.enable_home_gateway_omci)?'success':'neutral'">{{Number(d.enable_home_gateway_omci)?'ENABLED':'DISABLED'}}</NxBadge></td><td class="px-4 py-3"><div class="flex justify-end gap-2"><a :href="`/olt-management/ports?olt_id=${d.id}`" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold no-underline">Ports</a><a :href="`/olt-management/profiles?olt_id=${d.id}`" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold no-underline">Profiles</a><NxButton variant="secondary" @click="viewDevice=d;detailModal=true">View</NxButton><NxButton variant="secondary" @click="openEditDevice(d)">Edit</NxButton><NxButton variant="danger" @click="pendingDelete={kind:'device',row:d}">Delete</NxButton></div></td></tr></tbody></NxTableShell>
<NxTableShell v-if="mode==='ports'" min-width="1100px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Port</th><th class="px-4 py-3">Board</th><th class="px-4 py-3">Type</th><th class="px-4 py-3">Link</th><th class="px-4 py-3">Optic</th><th class="px-4 py-3">VLAN Access</th><th class="px-4 py-3">ONTs</th><th class="px-4 py-3 text-right">Action</th></tr></thead><tbody><tr v-if="!portRows.length"><td colspan="8" class="px-4 py-12 text-center">{{selectedOltId?'No imported ports found.':'Select an OLT.'}}</td></tr><tr v-for="p in portRows" :key="p.id"><td class="px-4 py-3 font-mono font-bold">{{portPath(p)}}</td><td class="px-4 py-3">{{p.board_name||p.board_type||'—'}}</td><td class="px-4 py-3">{{p.port_type||'—'}}</td><td class="px-4 py-3"><NxBadge :tone="tone(p.link_status)">{{p.link_status||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(p.optic_status)">{{p.optic_status||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3 font-mono">{{p.allowed_svlans_csv||p.svlan||'—'}}</td><td class="px-4 py-3">{{p.ont_online||0}} / {{p.ont_count||0}}</td><td class="px-4 py-3 text-right"><NxButton variant="secondary" @click="viewPort=p;portModal=true">View</NxButton></td></tr></tbody></NxTableShell>
<NxTableShell v-if="mode==='profiles'" min-width="640px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Profile</th><th class="px-4 py-3">Description</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!profileRows.length"><td colspan="3" class="px-4 py-12 text-center">{{selectedOltId?`No ${profileTab.toUpperCase()} profiles found.`:'Select an OLT.'}}</td></tr><tr v-for="p in profileRows" :key="p.id"><td class="px-4 py-3"><p class="font-semibold">{{p.profile_name||'Unnamed'}}</p><p class="text-xs text-[var(--nx-text-muted)]">ID {{p.profile_id||p.id}}</p></td><td class="px-4 py-3">{{p.description||'—'}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" title="View configuration" aria-label="View configuration" @click="showConfiguration(p)">Configuration</NxButton><NxButton variant="secondary" @click="showCli(p)">CLI</NxButton><NxButton variant="secondary" @click="openEditProfile(p)">Edit</NxButton><NxButton variant="danger" @click="pendingDelete={kind:'profile',row:p}">Delete</NxButton></div></td></tr></tbody></NxTableShell>
<NxModal :open="deviceModal" :title="editingDevice?'Edit OLT Device':'Add OLT Device'" description="Connection secrets are accepted by the backend but never rendered in device details." @close="deviceModal=false"><form @submit.prevent="submitDevice"><NxAlert v-if="modalError" tone="danger" class="mx-6 mt-5">{{modalError}}</NxAlert><div class="grid gap-4 bg-[var(--nx-canvas)] p-6 md:grid-cols-2"><label v-for="f in [['name','Device Name','text'],['ip_address','IP Address','text'],['vendor','Vendor','text'],['username','Username','text'],['password','Password','password']]" :key="f[0]" class="grid gap-1 text-sm font-semibold">{{f[1]}}<input v-model="deviceForm[f[0] as keyof OltDevicePayload]" :type="f[2]" required class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label v-for="f in [['enable_home_gateway_omci','Home Gateway OMCI'],['auto_detect_omci_support','Auto-detect OMCI']]" :key="f[0]" class="flex items-center gap-3"><input v-model="deviceForm[f[0] as keyof OltDevicePayload]" type="checkbox" :true-value="1" :false-value="0">{{f[1]}}</label></div><div class="flex justify-end gap-2 border-t p-5"><NxButton type="button" variant="secondary" @click="deviceModal=false">Cancel</NxButton><NxButton type="submit" :disabled="saving">{{saving?'Saving…':'Save Device'}}</NxButton></div></form></NxModal>
<NxModal :open="detailModal" title="OLT Device Details" description="Passwords are intentionally hidden." @close="detailModal=false"><dl class="grid gap-4 p-6 md:grid-cols-2"><div v-for="item in [['Device Name',viewDevice?.name],['IP Address',viewDevice?.ip_address],['Vendor',viewDevice?.vendor],['Username',viewDevice?.username],['Password','••••••••'],['Home Gateway OMCI',Number(viewDevice?.enable_home_gateway_omci)?'Enabled':'Disabled']]" :key="String(item[0])"><dt class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0]}}</dt><dd class="mt-1 font-semibold">{{item[1]||'—'}}</dd></div></dl><template #footer><NxButton @click="detailModal=false">Close</NxButton></template></NxModal>
<NxModal :open="portModal" title="OLT Port Details" :description="portPath(viewPort||{} as OltPort)" @close="portModal=false"><dl class="grid gap-4 p-6 md:grid-cols-2"><div v-for="item in Object.entries(viewPort||{}).filter(([k])=>!['id','olt_id'].includes(k))" :key="item[0]"><dt class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0].replaceAll('_',' ')}}</dt><dd class="mt-1 break-all font-semibold">{{item[1]??'—'}}</dd></div></dl><template #footer><NxButton @click="portModal=false">Close</NxButton></template></NxModal>
<NxModal :open="configurationModal" :title="`${viewConfiguration?.profile_name||'Profile'} Configuration`" :description="`${profileTab.toUpperCase()} profile ${viewConfiguration?.profile_id||viewConfiguration?.id||''}`" @close="configurationModal=false"><dl class="grid gap-3 p-6 sm:grid-cols-2"><div v-for="([key,value]) in configurationEntries(viewConfiguration)" :key="key" class="rounded-md bg-[var(--nx-surface-muted)] p-4"><dt class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{key.replaceAll('_',' ')}}</dt><dd class="mt-1 break-all font-mono text-sm">{{value??'—'}}</dd></div><div v-if="!configurationEntries(viewConfiguration).length" class="text-sm text-[var(--nx-text-muted)]">No additional configuration values.</div></dl><template #footer><NxButton @click="configurationModal=false">Close</NxButton></template></NxModal>
<NxModal :open="profileModal" :title="`${editingProfile?'Edit':'Add'} ${profileTab.toUpperCase()} Profile`" description="Profile changes use the existing OLT-specific backend workflow." @close="profileModal=false"><form @submit.prevent="submitProfile"><NxAlert v-if="modalError" tone="danger" class="mx-6 mt-5">{{modalError}}</NxAlert><div class="grid gap-4 bg-[var(--nx-canvas)] p-6 md:grid-cols-2"><label v-for="f in profileFields[profileTab]" :key="f[0]" class="grid gap-1 text-sm font-semibold">{{f[1]}}<input v-model="profileForm[f[0]]" :type="f[2]" :required="!['description','acs_username','acs_password'].includes(f[0])" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label></div><div class="flex justify-end gap-2 border-t p-5"><NxButton type="button" variant="secondary" @click="profileModal=false">Cancel</NxButton><NxButton type="submit" :disabled="saving">Save Profile</NxButton></div></form></NxModal><NxModal :open="cliModal" title="Generated CLI Preview" description="Read-only configuration preview." max-width="60rem" @close="cliModal=false"><pre class="m-6 max-h-[65vh] overflow-auto rounded-md bg-slate-950 p-4 text-xs text-slate-100">{{cli}}</pre><template #footer><NxButton @click="cliModal=false">Close</NxButton></template></NxModal><NxConfirmDialog :open="Boolean(pendingDelete)" :title="pendingDelete?.kind==='device'?'Delete OLT device?':'Delete OLT profile?'" :description="pendingDelete?.kind==='device'?'Deletion is blocked while the OLT has imported ports.':'The selected provisioning profile will be permanently removed.'" confirm-label="Delete" danger :busy="saving" :error="modalError" @close="pendingDelete=null" @confirm="executeDelete" /></div></template>
